import { BrowserRouter, Routes, Route, Navigate } from 'react-router-dom';
import Layout from '@/components/Layout';
import TaskListPage from '@/pages/TaskListPage';
import TaskDetailPage from '@/pages/TaskDetailPage';
import BoardPage from '@/pages/BoardPage';

export default function App() {
  return (
    <BrowserRouter>
      <Routes>
        <Route element={<Layout />}>
          <Route path="/" element={<TaskListPage />} />
          <Route path="/task" element={<TaskDetailPage />} />
          <Route path="/board" element={<BoardPage />} />
          <Route path="*" element={<Navigate to="/" replace />} />
        </Route>
      </Routes>
    </BrowserRouter>
  );
}

export type Priority = '高' | '中' | '低';
export type Status = '待开始' | '进行中' | '已完成';

export interface Task {
  id: number;
  title: string;
  assignee: string;
  due_date: string;
  priority: Priority;
  status: Status;
  description?: string;
}

export interface TaskFormData {
  title: string;
  description: string;
  assignee: string;
  due_date: string;
  priority: Priority;
}

import type { Task } from '@/types/task';

export const TASKS: Task[] = [
  { id: 1, title: '设计登录页面', assignee: '张伟', due_date: '2025-07-10', priority: '高', status: '进行中', description: '完成登录页面的 UI 设计与前端实现。' },
  { id: 2, title: '后端API接口开发', assignee: '李娜', due_date: '2025-07-15', priority: '高', status: '待开始', description: '开发用户认证与任务管理相关 REST API。' },
  { id: 3, title: '数据库优化', assignee: '王芳', due_date: '2025-07-20', priority: '中', status: '进行中', description: '对核心查询进行索引优化，提升响应速度。' },
  { id: 4, title: '单元测试编写', assignee: '刘洋', due_date: '2025-07-25', priority: '低', status: '已完成', description: '为核心业务逻辑编写单元测试，覆盖率达 80%。' },
  { id: 5, title: '部署上线', assignee: '陈静', due_date: '2025-07-30', priority: '高', status: '待开始', description: '配置 CI/CD 流水线并完成生产环境部署。' },
  { id: 6, title: '用户反馈收集', assignee: '赵磊', due_date: '2025-08-05', priority: '中', status: '进行中', description: '通过问卷和访谈收集用户使用反馈。' },
];

import { clsx, type ClassValue } from 'clsx';
import { twMerge } from 'tailwind-merge';

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

export function priorityClass(priority: string): string {
  const map: Record<string, string> = {
    '高': 'bg-red-100 text-red-700',
    '中': 'bg-amber-100 text-amber-700',
    '低': 'bg-green-100 text-green-700',
  };
  return map[priority] ?? 'bg-muted text-muted-foreground';
}

export function statusClass(status: string): string {
  const map: Record<string, string> = {
    '进行中': 'bg-indigo-100 text-indigo-700',
    '待开始': 'bg-slate-100 text-slate-600',
    '已完成': 'bg-emerald-100 text-emerald-700',
  };
  return map[status] ?? 'bg-muted text-muted-foreground';
}

import * as React from 'react';
import { Slot } from '@radix-ui/react-slot';
import { cva, type VariantProps } from 'class-variance-authority';
import { cn } from '@/lib/utils';

const buttonVariants = cva(
  'inline-flex items-center justify-center whitespace-nowrap rounded-md text-sm font-medium transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 disabled:pointer-events-none disabled:opacity-50',
  {
    variants: {
      variant: {
        default: 'bg-primary text-primary-foreground hover:bg-primary/90',
        destructive: 'bg-destructive text-destructive-foreground hover:bg-destructive/90',
        outline: 'border border-input bg-background hover:bg-accent hover:text-accent-foreground',
        secondary: 'bg-secondary text-secondary-foreground hover:bg-secondary/80',
        ghost: 'hover:bg-accent hover:text-accent-foreground',
        link: 'text-primary underline-offset-4 hover:underline',
      },
      size: {
        default: 'h-10 px-4 py-2',
        sm: 'h-9 rounded-md px-3',
        lg: 'h-11 rounded-md px-8',
        icon: 'h-10 w-10',
      },
    },
    defaultVariants: {
      variant: 'default',
      size: 'default',
    },
  }
);

export interface ButtonProps
  extends React.ButtonHTMLAttributes<HTMLButtonElement>,
    VariantProps<typeof buttonVariants> {
  asChild?: boolean;
}

const Button = React.forwardRef<HTMLButtonElement, ButtonProps>(
  ({ className, variant, size, asChild = false, ...props }, ref) => {
    const Comp = asChild ? Slot : 'button';
    return (
      <Comp
        className={cn(buttonVariants({ variant, size, className }))}
        ref={ref}
        {...props}
      />
    );
  }
);
Button.displayName = 'Button';

export { Button, buttonVariants };

