import { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { Search, Plus } from 'lucide-react';
import { TASKS } from '@/data/tasks';
import { priorityClass, statusClass } from '@/lib/utils';
import { Input } from '@/components/ui/input';
import { Button } from '@/components/ui/button';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import AvatarChip from '@/components/AvatarChip';

const STATS = [
  { label: '总任务', getValue: () => TASKS.length, colorClass: 'text-primary' },
  { label: '进行中', getValue: () => TASKS.filter((t) => t.status === '进行中').length, colorClass: 'text-amber-600' },
  { label: '已完成', getValue: () => TASKS.filter((t) => t.status === '已完成').length, colorClass: 'text-emerald-600' },
];

export default function TaskListPage() {
  const [search, setSearch] = useState('');
  const navigate = useNavigate();

  const filtered = TASKS.filter(
    (t) =>
      t.title.toLowerCase().includes(search.toLowerCase()) ||
      t.assignee.toLowerCase().includes(search.toLowerCase())
  );

  return (
    <div className="p-8">
      {/* Hero */}
      <div className="mb-8">
        <h1 className="text-2xl font-bold text-foreground">任务列表</h1>
        <p className="text-muted-foreground mt-1">管理和追踪所有项目任务</p>
      </div>

      {/* Stats */}
      <div className="grid grid-cols-1 sm:grid-cols-3 gap-4 mb-8">
        {STATS.map((s) => (
          <Card key={s.label}>
            <CardContent className="p-5">
              <p className="text-sm text-muted-foreground">{s.label}</p>
              <p className={`text-3xl font-bold mt-1 ${s.colorClass}`}>{s.getValue()}</p>
            </CardContent>
          </Card>
        ))}
      </div>

      {/* Table Card */}
      <Card>
        <CardHeader className="px-6 py-4 border-b border-border flex-row items-center justify-between space-y-0">
          <CardTitle className="text-base">所有任务</CardTitle>
          <div className="flex items-center gap-3">
            <div className="relative">
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
              <Input
                value={search}
                onChange={(e) => setSearch(e.target.value)}
                placeholder="搜索任务..."
                className="pl-9 w-48 h-9"
              />
            </div>
            <Button size="sm" onClick={() => navigate('/task')}>
              <Plus className="w-4 h-4 mr-1" />
              新建任务
            </Button>
          </div>
        </CardHeader>

        <div className="overflow-x-auto">
          <table className="w-full">
            <thead>
              <tr className="border-b border-border">
                {['任务名称', '负责人', '截止日期', '优先级', '状态'].map((h) => (
                  <th
                    key={h}
                    className="px-6 py-3 text-left text-xs font-semibold text-muted-foreground uppercase tracking-wide"
                  >
                    {h}
                  </th>
                ))}
              </tr>
            </thead>
            <tbody>
              {filtered.length === 0 && (
                <tr>
                  <td colSpan={5} className="px-6 py-10 text-center text-sm text-muted-foreground">
                    暂无匹配任务
                  </td>
                </tr>
              )}
              {filtered.map((task, i) => (
                <tr
                  key={task.id}
                  className={`border-b border-border/50 hover:bg-accent/50 transition-colors cursor-pointer ${
                    i % 2 !== 0 ? 'bg-muted/20' : ''
                  }`}
                  onClick={() => navigate('/task')}
                >
                  <td className="px-6 py-4 text-sm font-medium text-foreground">{task.title}</td>
                  <td className="px-6 py-4">
                    <AvatarChip name={task.assignee} />
                  </td>
                  <td className="px-6 py-4 text-sm text-muted-foreground">{task.due_date}</td>
                  <td className="px-6 py-4">
                    <span className={`px-2.5 py-1 rounded-full text-xs font-medium ${priorityClass(task.priority)}`}>
                      {task.priority}
                    </span>
                  </td>
                  <td className="px-6 py-4">
                    <span className={`px-2.5 py-1 rounded-full text-xs font-medium ${statusClass(task.status)}`}>
                      {task.status}
                    </span>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </Card>
    </div>
  );
}

import { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { CheckCircle2 } from 'lucide-react';
import type { Priority, TaskFormData } from '@/types/task';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Textarea } from '@/components/ui/textarea';
import { Label } from '@/components/ui/label';
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from '@/components/ui/card';
import { cn } from '@/lib/utils';

const PRIORITIES: Priority[] = ['高', '中', '低'];

const PRIORITY_ACTIVE: Record<Priority, string> = {
  高: 'bg-red-500 text-white border-red-500',
  中: 'bg-amber-500 text-white border-amber-500',
  低: 'bg-green-500 text-white border-green-500',
};

const DEFAULT_FORM: TaskFormData = {
  title: '',
  description: '',
  assignee: '',
  due_date: '',
  priority: '中',
};

export default function TaskDetailPage() {
  const navigate = useNavigate();
  const [form, setForm] = useState<TaskFormData>(DEFAULT_FORM);
  const [saved, setSaved] = useState(false);
  const [errors, setErrors] = useState<Partial<Record<keyof TaskFormData, string>>>({});

  function handle<K extends keyof TaskFormData>(key: K, value: TaskFormData[K]) {
    setForm((prev) => ({ ...prev, [key]: value }));
    if (errors[key]) setErrors((prev) => ({ ...prev, [key]: undefined }));
  }

  function validate(): boolean {
    const next: typeof errors = {};
    if (!form.title.trim()) next.title = '任务标题不能为空';
    if (!form.assignee.trim()) next.assignee = '负责人不能为空';
    if (!form.due_date) next.due_date = '请选择截止日期';
    setErrors(next);
    return Object.keys(next).length === 0;
  }

  function handleSubmit(e: React.FormEvent) {
    e.preventDefault();
    if (!validate()) return;
    setSaved(true);
    setTimeout(() => setSaved(false), 2500);
  }

  return (
    <div className="p-8">
      {/* Hero */}
      <div className="mb-8">
        <h1 className="text-2xl font-bold text-foreground">任务详情</h1>
        <p className="text-muted-foreground mt-1">创建或编辑任务信息</p>
      </div>

      <Card className="max-w-2xl">
        <CardHeader className="border-b border-border">
          <CardTitle>任务信息</CardTitle>
          <CardDescription>填写完整的任务信息后点击保存</CardDescription>
        </CardHeader>

        <CardContent className="pt-6">
          <form onSubmit={handleSubmit} noValidate className="space-y-5">
            {/* Title */}
            <div className="space-y-1.5">
              <Label htmlFor="title">
                任务标题 <span className="text-destructive">*</span>
              </Label>
              <Input
                id="title"
                value={form.title}
                onChange={(e) => handle('title', e.target.value)}
                placeholder="输入任务标题"
                className={cn(errors.title && 'border-destructive focus-visible:ring-destructive')}
              />
              {errors.title && <p className="text-xs text-destructive">{errors.title}</p>}
            </div>

            {/* Description */}
            <div className="space-y-1.5">
              <Label htmlFor="description">任务描述</Label>
              <Textarea
                id="description"
                value={form.description}
                onChange={(e) => handle('description', e.target.value)}
                placeholder="详细描述任务内容..."
                rows={4}
              />
            </div>

            {/* Assignee + Due Date */}
            <div className="grid grid-cols-2 gap-4">
              <div className="space-y-1.5">
                <Label htmlFor="assignee">
                  负责人 <span className="text-destructive">*</span>
                </Label>
                <Input
                  id="assignee"
                  value={form.assignee}
                  onChange={(e) => handle('assignee', e.target.value)}
                  placeholder="输入负责人姓名"
                  className={cn(errors.assignee && 'border-destructive focus-visible:ring-destructive')}
                />
                {errors.assignee && <p className="text-xs text-destructive">{errors.assignee}</p>}
              </div>
              <div className="space-y-1.5">
                <Label htmlFor="due_date">
                  截止日期 <span className="text-destructive">*</span>
                </Label>
                <Input
                  id="due_date"
                  type="date"
                  value={form.due_date}
                  onChange={(e) => handle('due_date', e.target.value)}
                  className={cn(errors.due_date && 'border-destructive focus-visible:ring-destructive')}
                />
                {errors.due_date && <p className="text-xs text-destructive">{errors.due_date}</p>}
              </div>
            </div>

            {/* Priority */}
            <div className="space-y-1.5">
              <Label>优先级</Label>
              <div className="flex gap-3">
                {PRIORITIES.map((p) => (
                  <button
                    key={p}
                    type="button"
                    onClick={() => handle('priority', p)}
                    className={cn(
                      'flex-1 py-2.5 rounded-md text-sm font-medium border transition-colors min-h-[44px]',
                      form.priority === p
                        ? PRIORITY_ACTIVE[p]
                        : 'bg-background text-muted-foreground border-input hover:border-primary/50'
                    )}
                  >
                    {p}
                  </button>
                ))}
              </div>
            </div>

            {/* Actions */}
            <div className="flex gap-3 pt-2">
              <Button type="submit" className="flex-1">
                {saved ? (
                  <span className="flex items-center gap-2">
                    <CheckCircle2 className="w-4 h-4" /> 已保存
                  </span>
                ) : (
                  '保存任务'
                )}
              </Button>
              <Button
                type="button"
                variant="outline"
                className="px-6"
                onClick={() => navigate('/')}
              >
                取消
              </Button>
            </div>
          </form>
        </CardContent>
      </Card>
    </div>
  );
}

import { TASKS } from '@/data/tasks';
