import { priorityClass } from '@/lib/utils';
import { Card } from '@/components/ui/card';
import AvatarChip from '@/components/AvatarChip';

interface Column {
  key: Status;
  label: string;
  headerClass: string;
  bgClass: string;
}

const COLUMNS: Column[] = [
  { key: '待开始', label: '待开始', headerClass: 'bg-slate-100 text-slate-600', bgClass: 'bg-slate-50' },
  { key: '进行中', label: '进行中', headerClass: 'bg-primary/10 text-primary', bgClass: 'bg-primary/5' },
  { key: '已完成', label: '已完成', headerClass: 'bg-emerald-100 text-emerald-700', bgClass: 'bg-emerald-50/50' },
];

export default function BoardPage() {
  return (
    <div className="p-8">
      {/* Hero */}
      <div className="mb-8">
        <h1 className="text-2xl font-bold text-foreground">看板视图</h1>
        <p className="text-muted-foreground mt-1">按状态查看任务进度</p>
      </div>

      {/* Board */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        {COLUMNS.map((col) => {
          const colTasks = TASKS.filter((t) => t.status === col.key);
          return (
            <div key={col.key} className={`rounded-xl p-4 ${col.bgClass}`}>
              {/* Column Header */}
              <div className="flex items-center justify-between mb-4">
                <span className={`px-3 py-1 rounded-full text-xs font-semibold ${col.headerClass}`}>
                  {col.label}
                </span>
                <span className="text-xs text-muted-foreground font-medium bg-background rounded-full px-2 py-0.5 border border-border">
                  {colTasks.length}
                </span>
              </div>

              {/* Task Cards */}
              <div className="space-y-3">
                {colTasks.length === 0 && (
                  <p className="text-xs text-muted-foreground text-center py-6">暂无任务</p>
                )}
                {colTasks.map((task) => (
                  <Card
                    key={task.id}
                    className="p-4 hover:shadow-md transition-shadow cursor-pointer"
                  >
                    <p className="text-sm font-semibold text-foreground mb-3 leading-snug">
                      {task.title}
                    </p>
                    <div className="flex items-center justify-between">
                      <AvatarChip name={task.assignee} size="sm" />
                      <span
                        className={`px-2 py-0.5 rounded-full text-xs font-medium ${priorityClass(task.priority)}`}
                      >
                        {task.priority}
                      </span>
                    </div>
                    {task.due_date && (
                      <p className="text-xs text-muted-foreground mt-2">{task.due_date}</p>
                    )}
                  </Card>
                ))}
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
